use super::{ffi,DirectEditor};use crate::theme::{Rgba,ScintillaTheme};use std::ffi::CString;pub const STYLE_DEFAULT:usize=32;
pub fn apply_theme(e:&DirectEditor,t:ScintillaTheme,font:&str,size:f32){let f=CString::new(font.replace('\0',"")).expect("font");e.send(ffi::SCI_STYLESETBACK,STYLE_DEFAULT,colour(t.background));e.send(ffi::SCI_STYLESETFORE,STYLE_DEFAULT,colour(t.foreground));e.send(ffi::SCI_STYLESETSIZE,STYLE_DEFAULT,size.round().clamp(8.,96.)as isize);e.send(ffi::SCI_STYLESETFONT,STYLE_DEFAULT,f.as_ptr()as isize);e.send(ffi::SCI_SETCARETFORE,0,colour(t.caret));e.send(ffi::SCI_SETCARETWIDTH,0,2)}fn colour(c:Rgba)->isize{((c.r as u32)<<16|((c.g as u32)<<8)|c.b as u32)as isize}
